// This page is opened straight off disk, where the async clipboard API can be missing or
// refused outright, so the old execCommand path stays as a fallback. A click that copies
// nothing must still say so: a silent no-op reads as a dead button.
function copyText(text) {
  if (navigator.clipboard && navigator.clipboard.writeText) return navigator.clipboard.writeText(text);
  return new Promise((resolve, reject) => {
    const scratch = document.createElement("textarea");
    scratch.value = text;
    scratch.setAttribute("readonly", "");
    scratch.style.position = "fixed";
    scratch.style.opacity = "0";
    document.body.appendChild(scratch);
    scratch.select();
    let copied = false;
    try { copied = document.execCommand("copy"); } catch (err) { copied = false; }
    document.body.removeChild(scratch);
    copied ? resolve() : reject(new Error("clipboard unavailable"));
  });
}
function handleCopyClick(btn) {
  const label = btn.querySelector(".cp-label");
  const flash = (text, cls) => {
    btn.classList.toggle("copied", cls === "copied");
    btn.classList.toggle("copyfail", cls === "copyfail");
    if (label) label.textContent = text;
    clearTimeout(btn._copyRevert);
    btn._copyRevert = setTimeout(() => {
      btn.classList.remove("copied", "copyfail");
      if (label) label.textContent = "Copy";
    }, 1400);
  };
  copyText(btn.dataset.copy)
    .then(() => flash("Copied", "copied"))
    .catch(() => flash("Press " + (navigator.platform.indexOf("Mac") === 0 ? "Cmd" : "Ctrl") + "+C", "copyfail"));
}

