    out=set()
    for n in d['nodes']:
        out.add(('id',n['id']))
        if n.get('name'): out.add(('name',n['name']))
    for e in d['edges']:
        out.add(('ref',e['a'])); out.add(('ref',e['b']))
    for a in d.get('acquaintances',[]):
        out.add(('ref',a['a'])); out.add(('ref',a['b']))
        for ev in a.get('evidence',[]):
            out.add(('ref',ev['chatId']))
            if ev.get('chatName'): out.add(('chatName',ev['chatName']))
    return out
