  if (p.met == null) return p.strength;
  if (T >= 1) return p.strength;
  if (T <= p.met) return 0;
  const life = (T - p.met) / (1 - p.met);
  let env;
  if (p.arch === "grow") env = Math.pow(life, 1.7);
  else if (p.arch === "steady") env = 0.25 + 0.75 * life;
  else if (p.arch === "burst") env = life < 0.8 ? 0.12 + 0.18 * life : 0.26 + (life - 0.8) * 3.7;
